import React from 'react';
import { Svg, Line, Circle, Text, G, Rect, Polygon } from '@react-pdf/renderer';
import {
  getEffectiveMezzanineDimensions,
  getValidFloorElevations,
} from './floorStructureConstants';

const AXIS_LABELS = ['А', 'Б', 'В', 'Г', 'Д', 'Е', 'Ж', 'И', 'К', 'Л'];

export default function PDFBuildingSectionEskiz({
  spanWidth = 18,
  spansCount = 1,
  height = 6,
  stories = 1,
  roofShape = 'gable',
  slope = 10,
  frameType = 'beam',
  cranes = [],
  spanOrientations = [],
  floorStructure = null,
  length = 48,
}) {
  const W_span = Number(spanWidth) > 0 ? Number(spanWidth) : 18;
  const numStories = Math.max(1, Math.min(5, Number(stories) || 1));
  
  let N_spans = Number(spansCount) || 1;
  if (Array.isArray(cranes) && cranes.length > N_spans) {
    N_spans = cranes.length;
  }
  N_spans = Math.max(1, Math.min(N_spans, 10));

  const H_clear = Number(height) > 0 ? Number(height) : 6;
  const S =
    slope !== undefined && slope !== null && slope !== "" && !isNaN(Number(slope))
      ? Number(slope)
      : 10;
  const isGable = String(roofShape) !== 'single';
  const isTruss = String(frameType) === 'truss';

  // 1. Определение высот балки / фермы
  let hBeamEave = 0.35;
  let hBeamMid = 0.35;

  if (isTruss) {
    let supportH = 0.35;
    if (W_span > 18 && W_span < 33) supportH = 0.35 + ((W_span - 18) * (0.75 - 0.35)) / (33 - 18);
    else if (W_span >= 33) supportH = 0.75;
    const trussAdd = S <= 21 ? 0.65 + (10 - S) * 0.0597 : 0;
    hBeamEave = supportH + trussAdd;
    hBeamMid = hBeamEave;
  } else {
    // Балка: дискретный ряд <= 12м, переменка > 12м
    if (W_span <= 12.0) {
      if (W_span <= 6.0) hBeamEave = 0.232;
      else if (W_span <= 8.0) hBeamEave = 0.268;
      else if (W_span <= 9.0) hBeamEave = 0.317;
      else if (W_span <= 10.0) hBeamEave = 0.391;
      else if (W_span <= 11.0) hBeamEave = 0.443;
      else if (W_span <= 11.5) hBeamEave = 0.515;
      else hBeamEave = 0.613;
      hBeamMid = hBeamEave;
    } else {
      if (W_span > 18 && W_span < 33) {
        hBeamEave = 0.35 + ((W_span - 18) * (0.75 - 0.35)) / (33 - 18);
      } else if (W_span >= 33) {
        hBeamEave = 0.75;
      } else {
        hBeamEave = 0.35;
      }
      // Высота по центру пролета (одинакова как для двухскатного, так и для односкатного)
      hBeamMid = Math.min(1.50, 2.0 * hBeamEave);
    }
  }

  const hPurlin = 0.2;
  const totalBuildingWidth = W_span * N_spans;
  const spanRise = isGable ? (W_span / 2) * (S / 100) : W_span * (S / 100);

  const H_eave_top = H_clear + hBeamEave;
  const H_max_roof = H_eave_top + spanRise + hPurlin;

  const svgWidth = 525;
  const svgHeight = 150;

  const padLeft = 45;
  const padRight = 35;
  const padBottom = 28;
  const padTop = 22;

  const drawAreaW = svgWidth - padLeft - padRight;
  const drawAreaH = svgHeight - padTop - padBottom;

  const scale = Math.min(drawAreaW / totalBuildingWidth, drawAreaH / (H_max_roof * 1.15));
  const realDrawW = totalBuildingWidth * scale;

  const offsetX = padLeft + (drawAreaW - realDrawW) / 2;
  const baseGroundY = svgHeight - padBottom;

  const yClear = baseGroundY - H_clear * scale;
  const yEaveTop = baseGroundY - H_eave_top * scale;

  const colXList = [];
  for (let i = 0; i <= N_spans; i++) {
    colXList.push(offsetX + i * (W_span * scale));
  }

  const bL = Number(length) || 36;
  const mezzDims = getEffectiveMezzanineDimensions(
    floorStructure,
    totalBuildingWidth,
    bL
  );
  const effectiveMezzWidth = mezzDims.width;
  const isPartialWidth = mezzDims.isCustomWidth;
  const mezzStartX = colXList[0];
  const mezzEndX = mezzStartX + effectiveMezzWidth * scale;
  const hitsMainCol = colXList.some((cx) => Math.abs(cx - mezzEndX) < 3);

  const floorHeight = H_clear / numStories;
  const floorLevels = [];
  const validElevs = getValidFloorElevations(numStories, H_clear, floorStructure?.storyElevations);
  for (let f = 1; f < numStories; f++) {
    const hLevel = validElevs[f - 1] !== undefined ? validElevs[f - 1] : ((f * H_clear) / numStories);
    const yLevel = baseGroundY - hLevel * scale;
    floorLevels.push({ index: f, hLevel, yLevel });
  }
  const topMezzanineY = floorLevels.length > 0 ? floorLevels[floorLevels.length - 1].yLevel : baseGroundY;

  const intermediateColsPerSpan = [];
  if (numStories > 1) {
    if (
      floorStructure?.columnSpansMode === "manual" &&
      Array.isArray(floorStructure?.columnSpans) &&
      floorStructure.columnSpans.length > 0
    ) {
      const rawSpans = floorStructure.columnSpans
        .map((v) => Number(v) || 0)
        .filter((v) => v > 0);
      if (rawSpans.length > 1) {
        const totalS = rawSpans.reduce((a, b) => a + b, 0) || W_span;
        let accum = 0;
        for (let s = 0; s < rawSpans.length - 1; s++) {
          accum += rawSpans[s];
          intermediateColsPerSpan.push(accum / totalS);
        }
      }
    } else {
      const kSubSpans = W_span >= 9 ? Math.floor(W_span / 9) + 1 : 1;
      if (kSubSpans > 1) {
        for (let s = 1; s < kSubSpans; s++) {
          intermediateColsPerSpan.push(s / kSubSpans);
        }
      }
    }
  }

  // Расчет координаты верха кровли в точке x внутри конкретного пролёта spanIndex
  const getSpanRoofTopY = (spanIdx, x) => {
    const spanX1 = colXList[spanIdx];
    const spanX2 = colXList[spanIdx + 1];
    if (isGable) {
      const spanMid = (spanX1 + spanX2) / 2;
      const ridgeY = yEaveTop - spanRise * scale;
      if (x <= spanMid) {
        return yEaveTop - ((x - spanX1) / (spanMid - spanX1)) * (yEaveTop - ridgeY);
      } else {
        return ridgeY + ((x - spanMid) / (spanX2 - spanMid)) * (yEaveTop - ridgeY);
      }
    } else {
      const ori = (spanOrientations && spanOrientations[spanIdx]) || 'right';
      const prog = Math.max(0, Math.min(1, (x - spanX1) / (spanX2 - spanX1)));
      if (ori === 'left') {
        return (yEaveTop - spanRise * scale) + prog * (spanRise * scale);
      } else {
        return yEaveTop - prog * (spanRise * scale);
      }
    }
  };

  const getRoofTopY = (x) => {
    const relX = x - offsetX;
    const spanIndex = Math.min(N_spans - 1, Math.max(0, Math.floor(relX / (W_span * scale))));
    return getSpanRoofTopY(spanIndex, x);
  };

  return (
    <Svg width={svgWidth} height={svgHeight}>
      {/* 1. Уровень пола */}
      <Line
        x1={colXList[0] - 15}
        y1={baseGroundY}
        x2={colXList[N_spans] + 15}
        y2={baseGroundY}
        stroke="#333333"
        strokeWidth={1}
      />

      {/* 2. Колонны и оси */}
      {colXList.map((x, i) => {
        const axisLabel = AXIS_LABELS[i] || `${i + 1}`;
        
        const leftSpanIdx = i > 0 ? i - 1 : null;
        const rightSpanIdx = i < N_spans ? i : null;

        const leftTop = leftSpanIdx !== null ? getSpanRoofTopY(leftSpanIdx, x) : null;
        const rightTop = rightSpanIdx !== null ? getSpanRoofTopY(rightSpanIdx, x) : null;

        const leftBot = leftTop !== null ? (isGable || isTruss ? yClear : leftTop + hBeamEave * scale) : null;
        const rightBot = rightTop !== null ? (isGable || isTruss ? yClear : rightTop + hBeamEave * scale) : null;

        const colTopY = Math.min(
          leftTop !== null ? leftTop : Infinity,
          rightTop !== null ? rightTop : Infinity
        );
        const colHeadY = Math.min(
          leftBot !== null ? leftBot : Infinity,
          rightBot !== null ? rightBot : Infinity
        );

        return (
          <G key={`col-axis-${i}`}>
            <Line
              x1={x}
              y1={colTopY - 10}
              x2={x}
              y2={baseGroundY + 12}
              stroke="#aaaaaa"
              strokeWidth={0.5}
              opacity={0.6}
            />

            {/* Колонна */}
            <Line
              x1={x}
              y1={baseGroundY}
              x2={x}
              y2={colHeadY}
              stroke="#007bff"
              strokeWidth={i === 0 || i === N_spans ? 2.5 : 2}
            />

            {/* Опорное ребро / стойка балки на оголовке */}
            <Line
              x1={x}
              y1={colHeadY}
              x2={x}
              y2={colTopY}
              stroke="#007bff"
              strokeWidth={1.2}
              opacity={0.8}
            />

            <Circle cx={x} cy={baseGroundY + 18} r={5.5} fill="#ffffff" stroke="#333333" strokeWidth={0.6} />
            <Text
              x={x}
              y={baseGroundY + 21.5}
              fontSize={7}
              fontFamily="Roboto"
              fill="#111111"
              textAnchor="middle"
            >
              {axisLabel}
            </Text>

            {i < N_spans && (
              <G key={`dim-span-${i}`}>
                <Line
                  x1={x}
                  y1={baseGroundY + 7}
                  x2={colXList[i + 1]}
                  y2={baseGroundY + 7}
                  stroke="#333333"
                  strokeWidth={0.5}
                />
                <Line x1={x} y1={baseGroundY + 9} x2={x} y2={baseGroundY + 5} stroke="#333333" strokeWidth={0.7} />
                <Line x1={colXList[i + 1]} y1={baseGroundY + 9} x2={colXList[i + 1]} y2={baseGroundY + 5} stroke="#333333" strokeWidth={0.7} />
                <Text
                  x={(x + colXList[i + 1]) / 2}
                  y={baseGroundY + 5}
                  fontSize={6}
                  fontFamily="Roboto"
                  fill="#111111"
                  textAnchor="middle"
                >
                  {`${W_span.toFixed(1)} м`}
                </Text>
              </G>
            )}
          </G>
        );
      })}

      {/* Габаритный размер всего здания */}
      {N_spans > 1 && (
        <G key="overall-building-dim">
          <Line
            x1={colXList[0]}
            y1={baseGroundY + 14}
            x2={colXList[N_spans]}
            y2={baseGroundY + 14}
            stroke="#555555"
            strokeWidth={0.5}
          />
          <Line x1={colXList[0]} y1={baseGroundY + 16} x2={colXList[0]} y2={baseGroundY + 12} stroke="#555555" strokeWidth={0.7} />
          <Line x1={colXList[N_spans]} y1={baseGroundY + 16} x2={colXList[N_spans]} y2={baseGroundY + 12} stroke="#555555" strokeWidth={0.7} />
          <Text
            x={(colXList[0] + colXList[N_spans]) / 2}
            y={baseGroundY + 13}
            fontSize={5.5}
            fontFamily="Roboto"
            fill="#333333"
            textAnchor="middle"
          >
            {`Общая ширина: ${totalBuildingWidth.toFixed(1)} м`}
          </Text>
        </G>
      )}

      {/* 3. Междуэтажные конструкции */}
      {numStories > 1 && (
        <G>
          {floorLevels.map((fl) => (
            <G key={`floor-level-beam-${fl.index}`}>
              <Line
                x1={mezzStartX}
                y1={fl.yLevel}
                x2={mezzEndX}
                y2={fl.yLevel}
                stroke="#0056b3"
                strokeWidth={2.2}
              />
              <Rect
                x={mezzStartX}
                y={fl.yLevel - 3}
                width={mezzEndX - mezzStartX}
                height={3}
                fill="#d0e2ff"
                stroke="#0056b3"
                strokeWidth={0.5}
              />
            </G>
          ))}

          {/* Крайняя стойка антресоли при неполной ширине */}
          {isPartialWidth && !hitsMainCol && (
            <G key="mezzanine-edge-col">
              <Line
                x1={mezzEndX}
                y1={baseGroundY}
                x2={mezzEndX}
                y2={topMezzanineY}
                stroke="#d97706"
                strokeWidth={1.8}
              />
              <Rect
                x={mezzEndX - 2}
                y={baseGroundY - 2.5}
                width={4}
                height={2.5}
                fill="#333333"
              />
            </G>
          )}

          {Array.from({ length: N_spans }).map((_, i) => {
            const x1 = colXList[i];
            const x2 = colXList[i + 1];
            if (x1 >= mezzEndX - 0.5) return null;
            return intermediateColsPerSpan.map((ratio, cIdx) => {
              const cx = x1 + ratio * (x2 - x1);
              if (cx > mezzEndX + 0.5) return null;
              return (
                <G key={`inter-col-${i}-${cIdx}`}>
                  <Line
                    x1={cx}
                    y1={baseGroundY}
                    x2={cx}
                    y2={topMezzanineY}
                    stroke="#007bff"
                    strokeWidth={1.8}
                  />
                  <Rect
                    x={cx - 2}
                    y={baseGroundY - 2.5}
                    width={4}
                    height={2.5}
                    fill="#333333"
                  />
                </G>
              );
            });
          })}
        </G>
      )}

      {/* 4. Ригель покрытия и кровля */}
      {Array.from({ length: N_spans }).map((_, i) => {
        const x1 = colXList[i];
        const x2 = colXList[i + 1];
        const xMid = (x1 + x2) / 2;

        const yTop1 = getSpanRoofTopY(i, x1);
        const yTop2 = getSpanRoofTopY(i, x2);
        const yTopMid = getSpanRoofTopY(i, xMid);

        // Точки низа балки
        const yBot1 = isGable ? yClear : (yTop1 + hBeamEave * scale);
        const yBot2 = isGable ? yClear : (yTop2 + hBeamEave * scale);
        const yBotMid = yTopMid + (hBeamMid * scale);

        const crane = Array.isArray(cranes) && cranes[i] ? cranes[i] : null;
        const hasCrane = Number(crane?.cap) > 0;
        const craneCap = crane?.cap || 0;
        const isSupport = !crane || crane.type !== 'suspension';
        
        const craneBaseY = numStories > 1 ? topMezzanineY : baseGroundY;
        const craneAvailableH = numStories > 1 ? (floorHeight * scale) : (H_clear * scale);
        const yBracket = craneBaseY - craneAvailableH * 0.7;

        const panelCount = Math.max(4, Math.round(W_span / 3));
        const spanNodes = [];
        for (let p = 0; p <= panelCount; p++) {
          const px = x1 + (p / panelCount) * (x2 - x1);
          const pyTop = getSpanRoofTopY(i, px);
          spanNodes.push({ x: px, yTop: pyTop, yBot: yClear });
        }

        return (
          <G key={`span-construct-${i}`}>
            {isTruss ? (
              <G>
                <Line x1={x1} y1={yClear} x2={x2} y2={yClear} stroke="#007bff" strokeWidth={1.5} />
                {isGable ? (
                  <G>
                    <Line x1={x1} y1={yTop1} x2={xMid} y2={yTopMid} stroke="#007bff" strokeWidth={1.8} />
                    <Line x1={xMid} y1={yTopMid} x2={x2} y2={yTop2} stroke="#007bff" strokeWidth={1.8} />
                  </G>
                ) : (
                  <Line x1={x1} y1={yTop1} x2={x2} y2={yTop2} stroke="#007bff" strokeWidth={1.8} />
                )}

                {spanNodes.map((node, nIdx) => {
                  const ori = (spanOrientations && spanOrientations[i]) || 'right';
                  let diagY1 = yClear;
                  let diagY2 = spanNodes[nIdx + 1]?.yTop || yClear;

                  if (isGable) {
                    diagY1 = nIdx >= panelCount / 2 ? node.yTop : yClear;
                    diagY2 = nIdx >= panelCount / 2 ? yClear : spanNodes[nIdx + 1]?.yTop;
                  } else {
                    if (ori === 'left') {
                      diagY1 = nIdx % 2 === 0 ? node.yTop : yClear;
                      diagY2 = nIdx % 2 === 0 ? yClear : spanNodes[nIdx + 1]?.yTop;
                    } else {
                      diagY1 = nIdx % 2 === 0 ? yClear : node.yTop;
                      diagY2 = nIdx % 2 === 0 ? spanNodes[nIdx + 1]?.yTop : yClear;
                    }
                  }

                  return (
                    <G key={`truss-web-${i}-${nIdx}`}>
                      <Line x1={node.x} y1={yClear} x2={node.x} y2={node.yTop} stroke="#007bff" strokeWidth={0.7} />
                      {nIdx < panelCount && (
                        <Line
                          x1={node.x}
                          y1={diagY1}
                          x2={spanNodes[nIdx + 1].x}
                          y2={diagY2}
                          stroke="#007bff"
                          strokeWidth={0.6}
                        />
                      )}
                    </G>
                  );
                })}
              </G>
            ) : (
              /* Балка: Двускатная или Односкатная */
              <G>
                {isGable ? (
                  <G>
                    <Polygon
                      points={`${x1},${yClear} ${x1},${yTop1} ${xMid},${yTopMid} ${x2},${yTop2} ${x2},${yClear} ${xMid},${yBotMid}`}
                      fill="#e3f2fd"
                      stroke="#007bff"
                      strokeWidth={1.8}
                    />
                    <Line x1={xMid} y1={yBotMid} x2={xMid} y2={yTopMid} stroke="#0056b3" strokeWidth={1.5} />
                    <Line x1={x1} y1={yClear} x2={x1} y2={yTop1} stroke="#0056b3" strokeWidth={1.5} />
                    <Line x1={x2} y1={yClear} x2={x2} y2={yTop2} stroke="#0056b3" strokeWidth={1.5} />
                  </G>
                ) : (
                  <G>
                    {/* Односкатная балка переменного сечения («рыбье пузо») */}
                    <Polygon
                      points={`${x1},${yBot1} ${x1},${yTop1} ${x2},${yTop2} ${x2},${yBot2} ${xMid},${yBotMid}`}
                      fill="#e3f2fd"
                      stroke="#007bff"
                      strokeWidth={1.8}
                    />
                    <Line x1={xMid} y1={yBotMid} x2={xMid} y2={yTopMid} stroke="#0056b3" strokeWidth={1.5} />
                    <Line x1={x1} y1={yBot1} x2={x1} y2={yTop1} stroke="#0056b3" strokeWidth={1.5} />
                    <Line x1={x2} y1={yBot2} x2={x2} y2={yTop2} stroke="#0056b3" strokeWidth={1.5} />
                  </G>
                )}
              </G>
            )}

            {/* Прогоны */}
            {spanNodes.map((node, pIdx) => (
              <Line
                key={`purlin-${i}-${pIdx}`}
                x1={node.x}
                y1={node.yTop}
                x2={node.x}
                y2={node.yTop - hPurlin * scale}
                stroke="#17a2b8"
                strokeWidth={1}
              />
            ))}

            {/* Кровля */}
            {isGable ? (
              <G>
                <Line x1={x1 - 2} y1={yTop1 - hPurlin * scale} x2={xMid} y2={yTopMid - hPurlin * scale} stroke="#28a745" strokeWidth={1.2} />
                <Line x1={xMid} y1={yTopMid - hPurlin * scale} x2={x2 + 2} y2={yTop2 - hPurlin * scale} stroke="#28a745" strokeWidth={1.2} />
              </G>
            ) : (
              <G>
                {/* Наклонный скат */}
                <Line
                  x1={x1 - (i === 0 ? 2 : 0)}
                  y1={yTop1 - hPurlin * scale}
                  x2={x2 + (i === N_spans - 1 ? 2 : 0)}
                  y2={yTop2 - hPurlin * scale}
                  stroke="#28a745"
                  strokeWidth={1.2}
                />
                {/* Вертикальный перепад (ступенька) */}
                {i < N_spans - 1 && (() => {
                  const nextYTop1 = getSpanRoofTopY(i + 1, x2);
                  if (Math.abs(yTop2 - nextYTop1) > 0.5) {
                    return (
                      <Line
                        x1={x2}
                        y1={yTop2 - hPurlin * scale}
                        x2={x2}
                        y2={nextYTop1 - hPurlin * scale}
                        stroke="#28a745"
                        strokeWidth={1.2}
                      />
                    );
                  }
                  return null;
                })()}
                {/* Торец крайней левой стены */}
                {i === 0 && (
                  <Line
                    x1={x1 - 2}
                    y1={yTop1 - hPurlin * scale}
                    x2={x1 - 2}
                    y2={yBot1}
                    stroke="#28a745"
                    strokeWidth={1}
                  />
                )}
                {/* Торец крайней правой стены */}
                {i === N_spans - 1 && (
                  <Line
                    x1={x2 + 2}
                    y1={yTop2 - hPurlin * scale}
                    x2={x2 + 2}
                    y2={yBot2}
                    stroke="#28a745"
                    strokeWidth={1}
                  />
                )}
              </G>
            )}

            {/* Краны */}
            {hasCrane && (
              <G key={`crane-span-${i}`}>
                {isSupport ? (
                  <G>
                    <Line x1={x1} y1={yBracket} x2={x1 + 4} y2={yBracket} stroke="#e65100" strokeWidth={1.5} />
                    <Line x1={x2} y1={yBracket} x2={x2 - 4} y2={yBracket} stroke="#e65100" strokeWidth={1.5} />
                    <Rect x={x1 + 2} y={yBracket - 3} width={2.5} height={3} fill="#e65100" />
                    <Rect x={x2 - 4.5} y={yBracket - 3} width={2.5} height={3} fill="#e65100" />
                    <Line x1={x1 + 4} y1={yBracket - 4} x2={x2 - 4} y2={yBracket - 4} stroke="#f57c00" strokeWidth={1.5} />
                    <Rect x={(x1 + x2) / 2 - 4} y={yBracket - 6.5} width={8} height={4} fill="#ffb74d" stroke="#e65100" strokeWidth={0.5} />
                    <Text
                      x={(x1 + x2) / 2}
                      y={yBracket - 8}
                      fontSize={5}
                      fontFamily="Roboto"
                      fill="#b33c00"
                      textAnchor="middle"
                    >
                      {`Кран ${craneCap} т`}
                    </Text>
                  </G>
                ) : (
                  <G>
                    <Line x1={x1 + 10} y1={yClear} x2={x1 + 10} y2={yClear + 5} stroke="#e65100" strokeWidth={1} />
                    <Line x1={x2 - 10} y1={yClear} x2={x2 - 10} y2={yClear + 5} stroke="#e65100" strokeWidth={1} />
                    <Line x1={x1 + 8} y1={yClear + 5} x2={x2 - 8} y2={yClear + 5} stroke="#f57c00" strokeWidth={1.5} />
                    <Text
                      x={(x1 + x2) / 2}
                      y={yClear + 12}
                      fontSize={5}
                      fontFamily="Roboto"
                      fill="#b33c00"
                      textAnchor="middle"
                    >
                      {`Подвесной кран ${craneCap} т`}
                    </Text>
                  </G>
                )}
              </G>
            )}
          </G>
        );
      })}

      {/* 5. Высотные отметки */}
      <Line x1={colXList[0] - 4} y1={baseGroundY} x2={colXList[0] - 12} y2={baseGroundY} stroke="#333333" strokeWidth={0.6} />
      <Text
        x={colXList[0] - 14}
        y={baseGroundY + 2}
        fontSize={6}
        fontFamily="Roboto"
        fill="#111111"
        textAnchor="end"
      >
        0.000
      </Text>

      {floorLevels.map((fl) => (
        <G key={`floor-level-mark-${fl.index}`}>
          <Line x1={colXList[0] - 4} y1={fl.yLevel} x2={colXList[0] - 12} y2={fl.yLevel} stroke="#0056b3" strokeWidth={0.6} />
          <Text
            x={colXList[0] - 14}
            y={fl.yLevel + 2}
            fontSize={5.5}
            fontFamily="Roboto"
            fill="#0056b3"
            textAnchor="end"
          >
            {`+${fl.hLevel.toFixed(2)}`}
          </Text>
        </G>
      ))}

      <Line x1={colXList[0] - 4} y1={yClear} x2={colXList[0] - 12} y2={yClear} stroke="#007bff" strokeWidth={0.6} />
      <Text
        x={colXList[0] - 14}
        y={yClear + 2}
        fontSize={6}
        fontFamily="Roboto"
        fill="#007bff"
        textAnchor="end"
      >
        {`+${H_clear.toFixed(2)}`}
      </Text>

      {isGable ? (
        colXList.slice(0, N_spans).map((x, i) => {
          const midX = (x + colXList[i + 1]) / 2;
          const ridgeY = getSpanRoofTopY(i, midX) - hPurlin * scale;
          return (
            <G key={`ridge-level-${i}`}>
              <Line x1={midX - 4} y1={ridgeY} x2={midX + 4} y2={ridgeY} stroke="#28a745" strokeWidth={0.6} />
              <Text
                x={midX}
                y={ridgeY - 3}
                fontSize={6}
                fontFamily="Roboto"
                fill="#1e7e34"
                textAnchor="middle"
              >
                {`+${(H_eave_top + (W_span / 2) * (S / 100) + hPurlin).toFixed(2)}`}
              </Text>
            </G>
          );
        })
      ) : (() => {
        const highPoints = [];
        for (let i = 0; i < N_spans; i++) {
          const ori = (spanOrientations && spanOrientations[i]) || 'right';
          const peakX = ori === 'left' ? colXList[i] : colXList[i + 1];
          const peakY = yEaveTop - spanRise * scale - hPurlin * scale;
          const hPeakVal = (H_eave_top + spanRise + hPurlin).toFixed(2);
          if (!highPoints.some((p) => Math.abs(p.x - peakX) < 2)) {
            highPoints.push({ x: peakX, y: peakY, hVal: hPeakVal, keyIdx: i });
          }
        }
        return highPoints.map((pt) => (
          <G key={`single-peak-level-${pt.keyIdx}-${pt.x}`}>
            <Line x1={pt.x - 4} y1={pt.y} x2={pt.x + 4} y2={pt.y} stroke="#28a745" strokeWidth={0.6} />
            <Text
              x={pt.x}
              y={pt.y - 3}
              fontSize={6}
              fontFamily="Roboto"
              fill="#1e7e34"
              textAnchor="middle"
            >
              {`+${pt.hVal}`}
            </Text>
          </G>
        ));
      })()}
    </Svg>
  );
}
